/* Original teaching cases. No participant data or real study findings. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.REILearningLab=api})(typeof window==='object'?window:globalThis,function(){
 'use strict';
 const titles=['Choose a topic','Define the problem','Search the literature','Compare the evidence','Locate a gap','Ask a research question','Set objectives','Plan the methodology','Build the proposal'];
 const entry=(draft,reason,limit)=>({draft,reason,limit});
 const cases={
  qualitative:{label:'Qualitative · experiences',title:'Making room for study',question:'How do first-year students with paid jobs at Harbor College describe arranging study time during an assessment week?',sources:[
   {id:'Q1',title:'Study routines and fixed shifts',method:'Invented interview study; 12 students at a commuter college.',finding:'Participants described moving study into short gaps between shifts.',limit:'One setting; accounts do not establish how common the pattern is.'},
   {id:'Q2',title:'Support and schedule flexibility',method:'Invented interview study; 10 residential students with flexible shifts.',finding:'Participants described negotiating shifts and using peer support.',limit:'A different setting and employment arrangement.'},
   {id:'Q3',title:'Study planning across a semester',method:'Invented survey; 90 working students.',finding:'Reported planning varied with scheduled work hours.',limit:'A numerical measure cannot explain what scheduling means to students.'}
  ],stages:[
   entry('I want to understand how first-year students with paid jobs arrange study time during assessment weeks at Harbor College.','A specific group, place and situation turn “student stress” into an explorable topic. The interest is in lived accounts, rather than a numerical estimate.','Access to students and permission to recruit still need checking.'),
   entry('Working students may face competing schedules during assessment weeks. The teaching collection suggests different strategies, but does not explain how students at Harbor College negotiate fixed shifts and study demands.','Separate a practical concern from what the study needs to understand. Q1 and Q2 suggest contrasting arrangements; neither describes this college.','This is a provisional problem, not evidence that all working students struggle.'),
   entry('Search combinations of (working student OR student employment) AND (study planning OR time management) AND (first year OR undergraduate). Record database, date, exact query and selection decisions. Compare Q1, Q2 and Q3 by setting and method.','Synonyms help locate related ideas. Q3 stays in the collection because a different method can illuminate the same topic.','Q1–Q3 are invented teaching records. Replace them with read, traceable publications in real work.'),
   entry('Q1 emphasizes fitting study around fixed shifts; Q2 emphasizes negotiating flexible shifts. These accounts can coexist because the settings and work arrangements differ. Q3 describes numerical variation but offers little explanation of negotiation.','Compare populations, collection and limits before treating findings as contradictory. An interpretation stays linked to the record that supports it.','The examples do not establish which strategy is better or how frequently it occurs.'),
   entry('Within this small teaching collection, accounts of negotiating fixed shifts during first-year assessment weeks at Harbor College are missing. I will search related commuter-college and assessment-week work before treating this as a defensible gap.','A bounded gap states what the reviewed collection cannot answer and names the next search.','Missing from three records does not mean missing from the entire literature.'),
   entry('How do first-year students with paid jobs at Harbor College describe arranging study time during an assessment week?','“How do they describe” calls for detailed accounts. Population, setting and time frame make the question researchable.','This question explores accounts; it cannot estimate prevalence or prove a causal effect.'),
   entry('Describe students’ reported scheduling strategies; explore the constraints and support they associate with those strategies; interpret similarities and differences across the accounts.','Each objective asks for an output that interviews can support. None promises improved grades or a campus-wide estimate.','Objectives may be revised after better literature review; document why they change.'),
   entry('Plan a qualitative interview study. Purposively recruit students meeting the first-year and paid-work criteria, seeking varied shift arrangements. Begin with a feasible small recruitment target agreed with the supervisor; justify adequacy using the question, diversity and depth of accounts. Use open prompts, review the guide, and document interview context. Read transcripts repeatedly, code relevant passages, develop and revise patterns of meaning, and write interpretations with contextualized extracts and reflexive notes. Obtain required institutional review before recruitment. Use voluntary consent and a separate protected location for recordings and identifiers.','Interviews provide accounts; purposive selection seeks relevant variation. Reflexive thematic analysis develops interpreted patterns rather than ranking themes by counts.','No universal interview count guarantees adequacy. Researcher interpretation, selective recruitment and one setting constrain transferability.'),
   entry('Working title: Making room for study. The proposal connects the bounded problem and provisional gap to the question, three objectives, purposive recruitment, interview guide and reflexive analysis. Include a literature matrix, consent and data-management plan, recruitment contingencies, timeline and explicit limitations. All activities remain planned.','A reviewer should be able to follow why each method answers an objective, and why each claim has a source.','No participants were recruited and no findings were produced. Institutional permission and feasibility remain unresolved.')
  ]},
  quantitative:{label:'Quantitative · associations',title:'Work hours and study planning',question:'Among first-year students with paid jobs at Harbor College, what is the association between weekly paid-work hours and planned study hours during an assessment week?',sources:[
   {id:'N1',title:'Work hours and planned study',method:'Invented cross-sectional survey; 120 students at a commuter college.',finding:'Students reporting more work hours tended to report fewer planned study hours.',limit:'Self-report and one-time measurement; no causal identification.'},
   {id:'N2',title:'Planning among working students',method:'Invented cross-sectional survey; 100 residential students.',finding:'No clear association was reported in this teaching record.',limit:'Different sample and planning measure; uncertainty needs inspection.'},
   {id:'N3',title:'Negotiating assessment weeks',method:'Invented interviews; 14 students with varied shifts.',finding:'Accounts describe commute time and shift flexibility as relevant to planning.',limit:'These accounts suggest possible factors, not numerical estimates.'}
  ],stages:[
   entry('I want to examine the association between weekly paid-work hours and planned study hours among first-year working students at Harbor College during an assessment week.','Two defined numerical variables create an association question. Keep the period and group explicit.','Planned study hours are not actual study time, learning or grades.'),
   entry('The teaching collection reports different associations between work and planning. Different measures and settings may explain this. The association at Harbor College, using hours measured over the same assessment week, is not described in the reviewed collection.','Name the uncertainty without assuming paid work causes poor performance. N1 and N2 motivate comparison; N3 suggests context worth considering.','This provisional rationale requires real literature, not these invented records.'),
   entry('Search (student employment OR paid work) AND (study hours OR study planning) AND (undergraduate OR first year). Record queries and selection criteria. Extract variable definitions, sample selection, context and uncertainty from N1–N3.','Searching for the constructs, rather than only the desired result, reduces one-sided selection.','Search beyond one database and keep contrary results. These records are teaching material only.'),
   entry('N1 reports an inverse association; N2 reports no clear association. Compare study-hour definitions, settings, sample selection, estimates and uncertainty before combining conclusions. N3 suggests commute and flexibility as possible alternative explanations.','An apparent disagreement prompts a methodological comparison. “No clear association” is not automatically evidence of exactly zero association.','The invented records contain no effect estimates or intervals, so their statistical disagreement cannot be resolved here.'),
   entry('The teaching collection lacks a directly comparable estimate for first-year working students at Harbor College during an assessment week. Search more broadly for equivalent measures and contexts, then explain why another estimate would matter.','A context gap needs a reason the setting may change interpretation, not simply a different location name.','A local project can be useful without claiming a globally novel discovery.'),
   entry('Among first-year students with paid jobs at Harbor College, what is the association between weekly paid-work hours and planned study hours during an assessment week?','The question specifies population, two variables and period. It deliberately asks for association.','An observational survey cannot by itself answer “Does paid work reduce study time?”'),
   entry('Describe the distributions of paid-work hours and planned study hours; estimate their association; discuss uncertainty and plausible alternative explanations such as commute time and shift flexibility.','Objectives point to descriptive summaries, an association estimate and qualified interpretation.','Collecting extra factors does not by itself remove confounding; the analytical role of each needs justification.'),
   entry('Plan a cross-sectional survey. Define hours in the same seven-day assessment period, distinguishing plans from actual activity. Seek a permitted sampling frame of eligible first-year working students. If feasible, randomly invite within programs and track invitations and responses; otherwise name the accessible volunteer sample honestly. Determine the recruitment target with a supervisor using the planned estimate, desired precision, expected response and resources. Check item comprehension with an approved small pretest before launch. Inspect missingness and distributions, plot paired hours, then choose and justify an association method suited to the data and assumptions. Report the estimate and appropriate uncertainty; discuss selection, recall and confounding. Participation is voluntary; avoid student IDs and employer names.','Aligned time windows make measurements comparable. Sampling affects the population that can be described; analysis must fit the measurement and observed data.','Random invitation does not guarantee representative responses. No fixed sample size or correlation method is automatically sufficient.'),
   entry('Working title: Work hours and study planning. Link the literature comparison to the association question, descriptive and analytical objectives, operational definitions, sampling frame, survey, analysis choices, uncertainty, ethics and timeline. State that the proposed study is observational. Include recruitment and nonresponse contingencies.','The proposal promises an estimate with limits, rather than a predetermined negative result or proof of causation.','This is a proposed study only. No survey, sample, statistical result or institutional approval exists.')
  ]}
 };
 const prompts=[
  ['Narrow “technology affects students” into a topic you could study this term. Explain what your version includes and leaves out.','Name a group and context; choose one phenomenon; explain access and what you are not trying to answer.','For example: how first-year commuters use reminders to plan assessment-week study. This narrows the group, activity and period; it does not claim reminders improve grades.'],
  ['Repair: “Students are lazy, so they fail.” Write a research problem that distinguishes an observation from an explanation.','Avoid blaming or assuming a cause; identify the uncertainty; name the evidence still needed.','A defensible problem might ask how students describe barriers to completing planned study. Failure and laziness are not established by the original statement; schedules, resources and other explanations need examination.'],
  ['A search returns only studies supporting your preferred result. Explain how you would revise it and document the decisions.','Use alternative terms; seek contrary findings; record queries and transparent inclusion decisions.','Search broader construct synonyms and contrasting findings, then log databases, dates and criteria. Do not discard a sound study because its result conflicts with your expectation.'],
  ['Two studies report different findings. Write a paragraph explaining two possible reasons and what you need to check before judging them.','Compare populations and context; compare measurements and methods; keep uncertainty visible.','A commuter-college interview and a residential-college survey may address different experiences and measures. Check the actual questions, sampling and analysis; do not average unlike findings or select a winner by sample count alone.'],
  ['Repair: “Nobody has researched this.” Write a bounded gap and one further search that could challenge it.','State the collection reviewed; explain the missing answer; propose a search that could disconfirm novelty.','Within the reviewed papers, assessment-week scheduling among first-year working commuters is not described. Search related terms and neighboring contexts before claiming the gap extends beyond this collection.'],
  ['Rewrite “Does work ruin grades?” as one experience question and one association question. Explain how the required evidence differs.','Specify group and period; avoid loaded causal wording; connect accounts versus measurements to each question.','Experience: how do first-year working students describe assessment-week study planning? Association: how are paid-work hours related to planned study hours in that week? Interviews can explore accounts; numerical paired measurements can estimate association. Neither alone establishes an effect on grades.'],
  ['A proposal promises to “understand experiences and prove an intervention works” using six interviews. Repair the objectives and explain the tradeoff.','Make each objective answerable; remove an unsupported causal promise; state what the revised study cannot conclude.','Describe experiences, explore constraints and interpret patterns in accounts. Interviews can support these objectives; demonstrating an intervention effect would require a different design and justification. Six interviews do not automatically ensure adequate depth or variation.'],
  ['Justify a collection, sampling and analysis plan for your question. Include one risk, one mitigation and a limitation the mitigation cannot remove.','Link all three decisions to the question; separate risk mitigation from approval; acknowledge selection or interpretation limits.','For an experience question, purposive interviews can seek relevant variation and interpret patterns. Voluntary private recruitment reduces pressure, but does not remove self-selection. Explain how recruitment, analysis, protected data handling and institutional review will actually work.'],
  ['A polished proposal has objectives that its methods cannot answer. Explain the revisions you would make before sharing it for review.','Trace each objective to evidence and analysis; check source support; distinguish planned work from completed findings.','Revise the objective or method until the chain is defensible, revisit any affected question and literature rationale, and flag unresolved access or ethics requirements. Good presentation and populated fields cannot certify research validity.']
 ];
 // Each choice has its own explanation. Correct positions deliberately vary.
 const q=(ask,options,correct,why)=>({ask,options,correct,why});
 const practice=[
  [q('Which topic is bounded enough for a term project?',['All causes of student stress worldwide','Study planning among first-year commuters during assessment week','Prove that every student needs an app'],1,['The population, causes and geography make this too broad to answer in one term.','This defines a group, activity and period; access and feasibility still need checking.','This assumes a result and treats an intervention as universally necessary.']),q('You can recruit only one campus club. What should change?',['Keep claiming all students are represented','Call the club a random sample','Bound the population claim and explain selection'],2,['An accessible group does not represent everyone automatically.','Convenience access is not random selection.','The reach of the claim should match the recruitment route and its limits.']),q('Which is a useful first step after noticing a problem?',['Check the context, available evidence and access','Write a conclusion immediately','Choose the most fashionable tool'],0,['A topic becomes researchable by checking what is known and what you can reasonably study.','A conclusion before inquiry prejudges the result.','A tool should follow the question and evidence need.'])],
  [q('“Low attendance proves students lack motivation.” What is missing?',['More confident wording','Evidence connecting attendance to motivation and consideration of alternatives','A more attractive chart'],1,['Confidence cannot repair an unsupported explanation.','Attendance is an observation; motivation is one possible explanation alongside illness, transport or work.','Presentation does not validate the explanatory claim.']),q('Which statement is a research problem?',['How students negotiate competing shifts and study demands is unclear in the reviewed context','We will distribute a questionnaire','The study will improve every student’s grades'],0,['This identifies an uncertainty that evidence could address.','This is a collection decision, not the problem it answers.','This promises impact before evidence and a suitable evaluation design exist.']),q('A supervisor asks for support for your problem. What do you provide?',['A confident personal opinion','A claim that everyone knows it','Traceable evidence, its context and its limitations'],2,['Personal experience can motivate inquiry but cannot support every population claim.','An appeal to common knowledge bypasses the evidence question.','Support must let another person inspect the basis and boundaries of your rationale.'])],
  [q('A good study contradicts your expectation. Should it be excluded?',['No; apply the same stated inclusion criteria','Yes; it makes the review inconsistent','Only if it has fewer participants'],0,['Criteria should concern relevance and quality, not whether you like the result.','Contrary evidence helps test and refine the explanation.','Sample size alone does not decide relevance or quality across different designs.']),q('Your query returns no papers. What follows?',['The topic is globally novel','Try related constructs, synonyms and another appropriate source','Invent a citation to complete the matrix'],1,['One unsuccessful query does not prove an absence of research.','A search failure may reflect vocabulary or coverage; document the revised strategy.','A fabricated citation cannot support a real project.']),q('What makes a search reproducible enough to discuss?',['Only a count of papers','Only the final bibliography','Database, date, exact query and selection reasons'],2,['A count does not explain how records were found or selected.','A bibliography omits unsuccessful searches and selection decisions.','This trail lets a reviewer inspect and challenge the scope of your search.'])],
  [q('Interview accounts and survey averages differ. What should you inspect first?',['Which paper has a nicer title','Whether they ask comparable questions in comparable contexts','Which result you prefer'],1,['A title does not establish comparability.','Different measures, populations and questions can produce compatible but different findings.','Preference introduces one-sided interpretation.']),q('One survey reports no clear association. What can you infer?',['The true association is exactly zero','All other studies are wrong','Inspect the estimate, uncertainty and design before interpreting'],2,['An inconclusive result is not automatically evidence of exactly zero association.','A single result does not overturn every other design and context.','Interpretation requires more than the presence or absence of a statistical label.']),q('Which literature note is most useful?',['Finding, source location, population, method and limitation','A pasted abstract alone','“Good paper” with no explanation'],0,['These fields support comparison and keep interpretation tied to inspectable evidence.','An abstract is a starting point; relevant claims and limitations need close reading.','A quality label without reasons cannot guide synthesis.'])],
  [q('Three papers omit your campus. Is that a global gap?',['Yes; a new location always guarantees novelty','No; describe the reviewed boundary and search further','Yes; if the proposal is long enough'],1,['A location difference needs a substantive rationale and wider literature checking.','The missing answer is bounded by the search you actually performed.','Length cannot establish novelty.']),q('Which gap is better justified?',['“No one has ever studied students”','“This is new because I thought of it”','“The reviewed studies do not explain fixed-shift negotiation; its relevance needs further checking”'],2,['This sweeping claim is implausible and unsupported.','Personal discovery is not evidence of a literature gap.','This identifies a specific missing explanation and keeps its status provisional.']),q('A new paper answers your proposed gap. What should you do?',['Reassess the rationale and question using the new evidence','Hide the paper','Keep claiming novelty because the draft is finished'],0,['Research is iterative; a defensible project can change as the collection grows.','Suppressing relevant evidence weakens the project.','Draft completion does not make the original claim true.'])],
  [q('Which question fits an interview study?',['What percentage of every student works?','Does paid work cause lower grades?','How do working students describe planning their study week?'],2,['Interviews with selected participants cannot estimate a population percentage by themselves.','A causal claim requires a design that addresses causal identification.','Accounts can explore experiences and meanings within an explicit context.']),q('A one-time survey measures work and study hours. Which wording fits?',['What is the association between the measured hours?','How much does work cause grades to fall?','Why does every student dislike studying?'],0,['Paired observational measurements can estimate association with stated limits.','The survey alone cannot establish causation and does not even measure grades.','This assumes a universal attitude and asks for an explanation the measures cannot provide.']),q('Changing an experience question to an effect question should trigger what?',['Only a title change','A review of evidence, sampling, collection, analysis and ethics','No changes if the form is complete'],1,['The evidence needed has changed, so the method chain needs review.','A new claim type can require an entirely different design and risk assessment.','Completeness does not establish fitness for a different question.'])],
  [q('Which objective fits an experience question?',['Prove a universal cause','Interpret the scheduling constraints described by participants','Estimate a campus percentage from selected interviews'],1,['A universal causal claim exceeds the evidence need and design.','The output is an interpretation of accounts that the study can collect.','Purposive interviews are not a campus probability survey.']),q('An objective says “collect questionnaires.” What is missing?',['The knowledge or estimate the activity should produce','A larger font','A claim that all answers will agree'],0,['An objective names what you seek to learn; collection is a means.','Formatting cannot clarify the intellectual output.','Agreement cannot be promised before data exist.']),q('Your objectives require data you cannot access. What next?',['Invent the unavailable data','Keep the objectives and omit the issue','Revise scope or access plans and discuss the consequences'],2,['Fabricated data cannot answer the question.','Hiding access problems makes the proposal infeasible.','An honest revision aligns the promised output with an achievable plan.'])],
  [q('A volunteer survey has 500 replies. What is still unresolved?',['Selection and nonresponse bias','Whether it looks substantial','Nothing; large samples guarantee representation'],0,['More replies do not automatically correct who had access or chose to respond.','Appearance is not a sampling justification.','A large selected sample can still give a biased picture of the intended population.']),q('For reflexive thematic analysis, a theme should be chosen only by how often a word appears.',['True; counts define meaning','False; develop and examine patterns of meaning in context','True; software decides interpretation'],1,['Repeated words can be clues but cannot define an interpreted theme on their own.','A theme is an interpreted pattern relevant to the question; retain context and reflexive reasoning.','Software can organize material but cannot supply a defensible interpretation by itself.']),q('A cross-sectional association supports which claim?',['Paid work definitely causes less study','Random sampling is the same as random treatment assignment','The variables are associated in the measured sample, with design limits'],2,['Timing, selection and alternative explanations prevent this automatic causal leap.','Sampling selects participants; assignment allocates a treatment. They address different problems.','Describe the estimate, uncertainty, measurement and sampling limits without converting association to causation.'])],
  [q('All readiness fields contain text. Does that validate the proposal?',['No; a reviewer must inspect the reasoning and evidence','Yes; completed forms certify validity','Yes; if all animations work'],0,['Recorded fields support review but do not certify their scientific content.','A field can contain a weak or mismatched plan.','Presentation quality does not demonstrate research validity.']),q('A planned survey is described as if results already exist. What is the repair?',['Invent plausible results','Use prospective language and separate expectations from findings','Remove the limitations'],1,['Plausibility does not make invented findings real.','A proposal explains intended work; results require actual approved collection and analysis.','Limitations help readers assess what the proposed study could support.']),q('A claim is supported by a citation you have not read. What should happen before sharing?',['Keep it because it looks credible','Replace it with an invented teaching record','Read and verify the source, qualify or remove the unsupported claim'],2,['A citation alone does not show the source supports the wording.','Teaching records are not publications and cannot support real research.','Traceability and accurate scope matter more than filling a reference list.'])]
 ];
 const glossary=[['Scope','The boundaries of a study: who or what, where, when and which phenomenon.'],['Research problem','An evidence-grounded uncertainty or issue that the study is designed to address.'],['Search strategy','The queries, sources and selection decisions used to locate relevant literature.'],['Synthesis','An interpretation across sources, including agreements, differences and limits.'],['Literature gap','A missing answer within a reviewed body of work; its extent depends on the search.'],['Construct','An idea, such as planning, that needs a clear definition and a defensible way to study it.'],['Objective','A specific knowledge output the study seeks, rather than simply a task to perform.'],['Operational definition','The exact way a variable is measured or categorized in this study.'],['Coherence','The fit between the problem, question, objectives, evidence and method plan.']];
 const methods=[
  {title:'Design follows the claim',body:'Start by deciding whether the question seeks experiences, a description, an association or a causal effect. Then explain the evidence that could answer it. Qualitative and quantitative approaches are broad families, not a quality ranking.',example:'An interview can explore how a shift feels disruptive. A survey can measure work and planned study hours. Neither alone shows that changing work hours causes a change in grades.',check:'Can each proposed conclusion be supported by what the design actually observes?',source:['Penn State · study design','https://online.stat.psu.edu/stat200/Lesson01']},
  {title:'Sampling sets the reach',body:'Name the intended population, who is eligible and how you will reach them. Distinguish random selection from accessible volunteers and purposive selection. Record who is excluded or may not respond.',example:'A club survey reaches club volunteers. Random invitations from an authorized list improve selection transparency, but nonresponse can still distort the result. Interviews may seek varied relevant experiences without estimating population percentages.',check:'Why is the selection appropriate, how is the target justified, and whose perspective might be missing?',source:['OpenStax · gathering data','https://openstax.org/books/contemporary-mathematics/pages/8-1-gathering-and-organizing-data']},
  {title:'Collection makes the question observable',body:'Specify what will be asked or measured, by whom, where and over what period. Define terms, avoid leading wording and plan missing-data handling. A pretest checks whether instructions and items are understandable; it is not proof of validity.',example:'Ask separately about paid-work hours and planned study hours in the same seven days. For interviews, use “Tell me about planning last week” before probes, rather than “How did work ruin your studying?”',check:'Would a participant understand the item in the way your analysis assumes?',source:null},
  {title:'Qualitative analysis needs interpretation',body:'For a reflexive thematic approach, become familiar with the material, code relevant passages, develop candidate patterns, examine them against the accounts, refine their meaning and write an interpretation. Keep notes about your standpoint and analytical decisions.',example:'“Moving study into gaps” could develop into a pattern about negotiating fragmented time. Examine contrasting accounts and context before making it a theme. A frequent word alone is not a theme.',check:'What meaning connects the extracts, what challenges your interpretation, and how did your role shape it?',source:['Braun & Clarke · reflexive thematic analysis','https://www.thematicanalysis.net/doing-reflexive-ta/']},
  {title:'Quantitative analysis needs a justified estimate',body:'Inspect coding, missingness, measurement scales and distributions before choosing a method. Match the analysis to the objective and its assumptions. Report an estimate and appropriate uncertainty, with a clear account of the sample and measurement limits.',example:'Plot paired work and planned study hours before selecting an association method. Discuss unusual observations and the pattern. A correlation is not a causal effect; an inconclusive estimate is not automatically an exact zero.',check:'What is estimated, which assumptions matter, and which alternative explanations remain?',source:['Penn State · sampling and study design','https://online.stat.psu.edu/stat100/Lesson02']},
  {title:'Ethics and limits are part of the design',body:'Explain voluntary consent, recruitment pressure, foreseeable risk, withdrawal arrangements, confidentiality, access, retention and deletion. Check institutional requirements before recruitment. Use an approved protected store for participant material; REI is a planning workspace.',example:'Do not recruit through a lecturer in a way that suggests grades depend on participation. Keep identifiers separate from research material and limit access. Removing names does not guarantee anonymity when contextual details identify someone.',check:'Who can access data, what happens if someone withdraws, and what limitation survives the mitigation?',source:null}
 ];
 function normalize(raw){const r=raw&&typeof raw==='object'?raw:{};const out={version:1,case:r.case==='quantitative'?'quantitative':'qualitative',support:['auto','guided','hints','independent'].includes(r.support)?r.support:'auto',attempts:{}};for(let i=0;i<9;i++){const a=r.attempts?.[i];if(!a||typeof a!=='object')continue;const valid=n=>Number.isInteger(n)&&n>=0&&n<3?n:null;out.attempts[i]={choices:Array.from({length:3},(_,n)=>valid(a.choices?.[n])),submitted:Array.from({length:3},(_,n)=>{const v=valid(a.submitted?.[n]);return v===valid(a.choices?.[n])?v:null}),reflection:typeof a.reflection==='string'?a.reflection.slice(0,100000):'',compared:a.compared===true&&typeof a.reflection==='string'&&!!a.reflection.trim()}}return out}
 function support(stage,pref){return pref==='auto'?(stage<3?'guided':stage<6?'hints':'independent'):pref}
 function attempt(raw,stage){return normalize(raw).attempts[stage]||{choices:[null,null,null],submitted:[null,null,null],reflection:'',compared:false}}
 function feedback(stage,item,choice){const x=practice[stage]?.[item];return x&&Number.isInteger(choice)&&choice>=0&&choice<3?{correct:choice===x.correct,text:x.why[choice]}:null}
 function decide(goal,collection,sampling){
  const g=['experience','association','effect'].includes(goal)?goal:'experience';const c=['interview','survey','trial'].includes(collection)?collection:'interview';const s=sampling==='structured'?'structured':'volunteer';
  const fit=(g==='experience'&&c==='interview')||(g==='association'&&c==='survey')||(g==='effect'&&c==='trial');
  const need={experience:'Detailed accounts and their context',association:'Paired measurements in a defined period',effect:'A defensible comparison under assigned conditions'}[g];
  const analysis={interview:'Interpret patterns of meaning in accounts',survey:'Describe variables and estimate their association',trial:'Compare outcomes under assigned conditions'}[c];
  const reach=s==='volunteer'?'Accessible volunteers: selection limits remain.':'Planned selection: define eligibility, frame and nonresponse; for interviews, justify relevant variation.';
  const claim=c==='interview'?'Accounts can illuminate experiences; they do not estimate a campus percentage.':c==='survey'?'An observational association does not establish an effect.': 'Random assignment can support causal inference under a valid design; adherence, attrition, measures and ethics still matter.';
  const explanation=fit?'The selected collection can supply the type of evidence the question asks for. You still need a justified sampling, measurement and analysis plan.':'The evidence and intended claim do not yet fit. Revise the question or the collection; adding more participants does not repair this mismatch.';
  return {fit,need,analysis,reach,claim,explanation};
 }
 return {titles,cases,practice,prompts,glossary,methods,normalize,support,attempt,feedback,decide};
});
